import sys

def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    nums = list(map(int, data[2:2 + n]))
    lo, hi = min(nums), max(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        cnt = 0
        i = 0
        while i < n:
            if nums[i] <= mid:
                cnt += 1
                i += 2
            else:
                i += 1
        if cnt >= k:
            hi = mid
        else:
            lo = mid + 1
    print(lo)

